<div class="si-wrap">
  <div class="si-head">
    <div><h3><i class="fa-solid fa-circle-info"></i> About System</h3><p>สถานะทรัพยากรและข้อมูลการทำงานของเครื่อง M1</p></div>
    <div class="si-live"><i></i><span id="siUpdated">กำลังโหลด...</span></div>
  </div>
  <div class="si-metrics">
    <article class="si-card cpu"><div class="si-card-head"><span><i class="fa-solid fa-microchip"></i> CPU</span><strong id="siCpu">—</strong></div><div class="si-progress"><i id="siCpuBar"></i></div><small id="siCpuMeta">—</small></article>
    <article class="si-card memory"><div class="si-card-head"><span><i class="fa-solid fa-memory"></i> Memory</span><strong id="siMemory">—</strong></div><div class="si-progress"><i id="siMemoryBar"></i></div><small id="siMemoryMeta">—</small></article>
    <article class="si-card disk"><div class="si-card-head"><span><i class="fa-solid fa-hard-drive"></i> Disk</span><strong id="siDisk">—</strong></div><div class="si-progress"><i id="siDiskBar"></i></div><small id="siDiskMeta">—</small></article>
    <article class="si-card temp"><div class="si-card-head"><span><i class="fa-solid fa-temperature-half"></i> Temperature</span><strong id="siTemp">—</strong></div><div class="si-temp-scale"><i id="siTempBar"></i></div><small>อุณหภูมิ CPU/System</small></article>
  </div>
  <div class="si-grid">
    <section class="si-panel"><div class="si-panel-head"><i class="fa-solid fa-server"></i><div><b>System Information</b><small>ข้อมูลเครื่องและระบบปฏิบัติการ</small></div></div><dl><div><dt>Hostname</dt><dd id="siHostname">—</dd></div><div><dt>Device model</dt><dd id="siModel">—</dd></div><div><dt>Operating system</dt><dd id="siOs">—</dd></div><div><dt>Kernel</dt><dd id="siKernel">—</dd></div><div><dt>Architecture</dt><dd id="siArch">—</dd></div><div><dt>Uptime</dt><dd id="siUptime">—</dd></div></dl></section>
    <section class="si-panel"><div class="si-panel-head"><i class="fa-solid fa-gauge-high"></i><div><b>Runtime Status</b><small>สถานะบริการและโหลดเฉลี่ย</small></div></div><div class="si-service"><span><i class="fa-brands fa-python"></i><b>py_multi.service</b></span><strong id="siService">—</strong></div><div class="si-load"><small>Load average</small><div><span><b id="siLoad1">—</b><small>1 นาที</small></span><span><b id="siLoad5">—</b><small>5 นาที</small></span><span><b id="siLoad15">—</b><small>15 นาที</small></span></div></div></section>
  </div>
</div>
<style>
.si-wrap{max-width:1180px;margin:0 auto;color:#26394e}.si-head{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:14px;padding:17px 19px;border:1px solid #e1e8f0;border-radius:16px;background:#fff;box-shadow:0 8px 22px rgba(31,55,89,.05)}.si-head h3{margin:0;font-size:1.15rem}.si-head h3 i{margin-right:7px;color:#1769d2}.si-head p{margin:3px 0 0;color:#718096;font-size:.78rem}.si-live{display:flex;align-items:center;gap:7px;padding:6px 10px;border-radius:20px;background:#edf8f3;color:#168958;font-size:.68rem}.si-live>i{width:8px;height:8px;border-radius:50%;background:#25a56a;box-shadow:0 0 0 4px rgba(37,165,106,.12);animation:siPulse 1.8s infinite}.si-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.si-card,.si-panel{padding:16px;border:1px solid #e1e8f0;border-radius:14px;background:#fff;box-shadow:0 7px 20px rgba(31,55,89,.045)}.si-card-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.si-card-head span{font-size:.73rem;font-weight:750;color:#53677e}.si-card-head span i{margin-right:5px}.si-card-head strong{font-size:1.12rem}.si-card small{display:block;margin-top:8px;color:#7c8c9d;font-size:.64rem}.si-progress,.si-temp-scale{height:7px;margin-top:13px;overflow:hidden;border-radius:8px;background:#edf1f5}.si-progress i,.si-temp-scale i{display:block;width:0;height:100%;border-radius:inherit;transition:width .4s}.si-card.cpu .si-progress i{background:#1769d2}.si-card.memory .si-progress i{background:#7457d9}.si-card.disk .si-progress i{background:#f0a31a}.si-card.temp .si-temp-scale i{background:linear-gradient(90deg,#25a56a,#f0a31a,#dc4a4a)}.si-card.cpu .si-card-head i{color:#1769d2}.si-card.memory .si-card-head i{color:#7457d9}.si-card.disk .si-card-head i{color:#e59400}.si-card.temp .si-card-head i{color:#dc4a4a}.si-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:12px;margin-top:12px}.si-panel-head{display:flex;align-items:center;gap:10px;padding-bottom:12px;border-bottom:1px solid #e8edf3}.si-panel-head>i{display:grid;place-items:center;width:34px;height:34px;border-radius:9px;background:#eaf3ff;color:#1769d2}.si-panel-head b,.si-panel-head small{display:block}.si-panel-head b{font-size:.82rem}.si-panel-head small{margin-top:2px;color:#7b8c9e;font-size:.64rem}.si-panel dl{margin:8px 0 0}.si-panel dl>div{display:grid;grid-template-columns:140px minmax(0,1fr);gap:12px;padding:8px 0;border-bottom:1px solid #f0f3f6}.si-panel dl>div:last-child{border:0}.si-panel dt{color:#718397;font-size:.69rem}.si-panel dd{min-width:0;margin:0;color:#314b65;font-size:.72rem;font-weight:700;overflow-wrap:anywhere}.si-service{display:flex;align-items:center;justify-content:space-between;margin-top:12px;padding:11px;border:1px solid #e2e9f0;border-radius:10px;background:#f8fafc}.si-service span{display:flex;align-items:center;gap:8px;font-size:.72rem}.si-service span i{color:#3978b7;font-size:1rem}.si-service strong{padding:3px 8px;border-radius:10px;font-size:.65rem}.si-service strong.active{background:#e5f7ee;color:#168958}.si-service strong.inactive{background:#fdeaea;color:#c53c3c}.si-load{margin-top:14px}.si-load>small{color:#718397;font-size:.68rem}.si-load>div{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:7px}.si-load span{padding:10px 5px;border-radius:9px;background:#f3f7fb;text-align:center}.si-load b,.si-load span small{display:block}.si-load b{color:#315b87;font-size:.92rem}.si-load span small{margin-top:2px;color:#8795a5;font-size:.58rem}@keyframes siPulse{50%{opacity:.45}}@media(max-width:900px){.si-metrics{grid-template-columns:1fr 1fr}.si-grid{grid-template-columns:1fr}}@media(max-width:560px){.si-head{align-items:flex-start;flex-direction:column}.si-live{align-self:stretch}.si-metrics{grid-template-columns:1fr}.si-panel dl>div{grid-template-columns:1fr;gap:3px}}
</style>
<script>
(()=>{
  const formatBytes=value=>{const number=Number(value||0);if(number<1024)return number+' B';const units=['KB','MB','GB','TB'];let size=number,index=-1;do{size/=1024;index++;}while(size>=1024&&index<units.length-1);return size.toFixed(size>=10?1:2)+' '+units[index];};
  const uptime=value=>{let seconds=Math.max(0,Number(value||0));const days=Math.floor(seconds/86400);seconds%=86400;const hours=Math.floor(seconds/3600);const minutes=Math.floor((seconds%3600)/60);return (days?days+' วัน ':'')+hours+' ชั่วโมง '+minutes+' นาที';};
  const text=(id,value)=>document.getElementById(id).textContent=value;
  const bar=(id,value)=>document.getElementById(id).style.width=Math.max(0,Math.min(100,Number(value||0)))+'%';
  let loading=false;
  function loadSystemInfo(){
    if(loading)return;loading=true;
    fetch('./system_info_api.php',{cache:'no-store'}).then(async response=>{const data=await response.json();if(!response.ok||data.error)throw Error(data.error||('HTTP '+response.status));return data;}).then(data=>{
      text('siCpu',data.cpu.percent.toFixed(1)+'%');bar('siCpuBar',data.cpu.percent);text('siCpuMeta',data.cpu.cores+' cores · Load '+data.cpu.load[0]);
      text('siMemory',data.memory.percent.toFixed(1)+'%');bar('siMemoryBar',data.memory.percent);text('siMemoryMeta',formatBytes(data.memory.used)+' / '+formatBytes(data.memory.total));
      text('siDisk',data.disk.percent.toFixed(1)+'%');bar('siDiskBar',data.disk.percent);text('siDiskMeta',formatBytes(data.disk.used)+' / '+formatBytes(data.disk.total));
      text('siTemp',data.cpu.temperature===null?'—':data.cpu.temperature.toFixed(1)+' °C');bar('siTempBar',data.cpu.temperature===null?0:data.cpu.temperature);
      text('siHostname',data.system.hostname);text('siModel',data.system.model);text('siOs',data.system.os);text('siKernel',data.system.kernel);text('siArch',data.system.architecture);text('siUptime',uptime(data.system.uptime_seconds));
      text('siLoad1',data.cpu.load[0]);text('siLoad5',data.cpu.load[1]);text('siLoad15',data.cpu.load[2]);
      const service=document.getElementById('siService');service.textContent=data.services.py_multi==='active'?'กำลังทำงาน':'หยุดทำงาน';service.className=data.services.py_multi;
      text('siUpdated','อัปเดต '+data.timestamp);
    }).catch(error=>text('siUpdated','โหลดข้อมูลไม่สำเร็จ: '+error.message)).finally(()=>loading=false);
  }
  loadSystemInfo();setInterval(()=>{if(!document.hidden)loadSystemInfo();},5000);
})();
</script>
